// The SBOMs under testdata/tomcat-9.0.98-jdk17 were generated by syft 1.51.1 from the image of
// https://github.com/anchore/grant/issues/217 (tomcat:9.0.98-jdk17), one per format from the same
// scan, and trimmed to five packages:
//
//   - catalina: declared Apache-2.0
//   - libexpat1: declared MIT
//   - fontconfig: concluded HPND-sell-variant, nothing declared
//   - libapr1t64: concluded Apache-2.0, BSD-4-Clause-UC, ISC and Zlib, nothing declared
//   - openssl: no licenses
//
// SPDX JSON and syft JSON record which licenses are concluded. CycloneDX as written and decoded by
// syft does not, so every license in it is read as declared.
const (
	tomcatSPDX      = "sbom.spdx.json"
	tomcatSyftJSON  = "sbom.syft.json"
	tomcatCycloneDX = "sbom.cdx.json"
)

func tomcatSBOM(name string) string {
	return filepath.Join("testdata", "tomcat-9.0.98-jdk17", name)
}

// concludedFinding is the part of a package finding these tests look at
type concludedFinding struct {
	decision string
	licenses []string
}

func findingsByPackage(t *testing.T, response *RunResponse) (TargetEvaluation, map[string]concludedFinding) {
	t.Helper()
	require.Len(t, response.Run.Targets, 1)
	evaluation := response.Run.Targets[0].Evaluation

	findings := make(map[string]concludedFinding)
	for _, p := range evaluation.Findings.Packages {
		f := concludedFinding{decision: p.Decision, licenses: []string{}}
		for _, l := range p.Licenses {
			f.licenses = append(f.licenses, l.ID)
		}
		findings[p.Name] = f
	}
	return evaluation, findings
}

func assertConcludedFindings(t *testing.T, want, got map[string]concludedFinding) {
	t.Helper()
	require.Len(t, got, len(want))
	for name, w := range want {
		g, ok := got[name]
		if !assert.True(t, ok, "package %q missing from the findings", name) {
			continue
		}
		assert.Equal(t, w.decision, g.decision, "decision for %q", name)
		assert.ElementsMatch(t, w.licenses, g.licenses, "licenses for %q", name)
	}
}

func TestCheck_IgnoreConcludedLicenses(t *testing.T) {
	allow := []string{"MIT", "Apache-2.0"}

	// what every format reports when concluded licenses are judged like declared ones: a denied
	// package lists the licenses that denied it
	concludedJudged := map[string]concludedFinding{
		"catalina":   {decision: DecisionAllow, licenses: []string{"Apache-2.0"}},
		"libexpat1":  {decision: DecisionAllow, licenses: []string{"MIT"}},
		"openssl":    {decision: DecisionAllow, licenses: []string{}},
		"fontconfig": {decision: DecisionDeny, licenses: []string{"HPND-sell-variant"}},
		"libapr1t64": {decision: DecisionDeny, licenses: []string{"BSD-4-Clause-UC", "ISC", "Zlib"}},
	}
	concludedIgnored := map[string]concludedFinding{
		"catalina":   {decision: DecisionAllow, licenses: []string{"Apache-2.0"}},
		"libexpat1":  {decision: DecisionAllow, licenses: []string{"MIT"}},
		"openssl":    {decision: DecisionAllow, licenses: []string{}},
		"fontconfig": {decision: DecisionAllow, licenses: []string{}},
		"libapr1t64": {decision: DecisionAllow, licenses: []string{}},
	}

	tests := []struct {
		name           string
		sbom           string
		policy         *Policy
		wantStatus     string
		wantUnlicensed int
		wantFindings   map[string]concludedFinding
	}{
		// the option is unset: this is the behavior grant had before the option existed
		{
			name:           "SPDX by default",
			sbom:           tomcatSPDX,
			policy:         &Policy{Allow: allow},
			wantStatus:     StatusNonCompliant,
			wantUnlicensed: 1,
			wantFindings:   concludedJudged,
		},
		{
			name:           "syft JSON by default",
			sbom:           tomcatSyftJSON,
			policy:         &Policy{Allow: allow},
			wantStatus:     StatusNonCompliant,
			wantUnlicensed: 1,
			wantFindings:   concludedJudged,
		},
		{
			name:           "CycloneDX by default",
			sbom:           tomcatCycloneDX,
			policy:         &Policy{Allow: allow},
			wantStatus:     StatusNonCompliant,
			wantUnlicensed: 1,
			wantFindings:   concludedJudged,
		},
		{
			name:           "SPDX ignoring concluded",
			sbom:           tomcatSPDX,
			policy:         &Policy{Allow: allow, IgnoreConcludedLicenses: true},
			wantStatus:     StatusCompliant,
			wantUnlicensed: 3,
			wantFindings:   concludedIgnored,
		},
		{
			name:           "syft JSON ignoring concluded",
			sbom:           tomcatSyftJSON,
			policy:         &Policy{Allow: allow, IgnoreConcludedLicenses: true},
			wantStatus:     StatusCompliant,
			wantUnlicensed: 3,
			wantFindings:   concludedIgnored,
		},
		{
			// CycloneDX does not say which licenses are concluded, so nothing is ignored
			name:           "CycloneDX ignoring concluded",
			sbom:           tomcatCycloneDX,
			policy:         &Policy{Allow: allow, IgnoreConcludedLicenses: true},
			wantStatus:     StatusNonCompliant,
			wantUnlicensed: 1,
			wantFindings:   concludedJudged,
		},
		{
			// a package left with no licenses is subject to require-license like any other
			name:           "SPDX ignoring concluded with require-license",
			sbom:           tomcatSPDX,
			policy:         &Policy{Allow: allow, IgnoreConcludedLicenses: true, RequireLicense: true},
			wantStatus:     StatusNonCompliant,
			wantUnlicensed: 3,
			wantFindings: map[string]concludedFinding{
				"catalina":   {decision: DecisionAllow, licenses: []string{"Apache-2.0"}},
				"libexpat1":  {decision: DecisionAllow, licenses: []string{"MIT"}},
				"openssl":    {decision: DecisionDeny, licenses: []string{}},
				"fontconfig": {decision: DecisionDeny, licenses: []string{}},
				"libapr1t64": {decision: DecisionDeny, licenses: []string{}},
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			orchestrator, err := NewOrchestrator(tt.policy)
			require.NoError(t, err)
			defer orchestrator.Close()

			response, err := orchestrator.Check([]string{"grant", "check"}, tomcatSBOM(tt.sbom))
			require.NoError(t, err)

			evaluation, findings := findingsByPackage(t, response)
			assert.Equal(t, tt.wantStatus, evaluation.Status)
			assert.Equal(t, 5, evaluation.Summary.Packages.Total)
			assert.Equal(t, tt.wantUnlicensed, evaluation.Summary.Packages.Unlicensed)
			assertConcludedFindings(t, tt.wantFindings, findings)
		})
	}
}

func TestList_IgnoreConcludedLicenses(t *testing.T) {
	declaredOnly := map[string]concludedFinding{
		"catalina":   {decision: DecisionUnevaluated, licenses: []string{"Apache-2.0"}},
		"libexpat1":  {decision: DecisionUnevaluated, licenses: []string{"MIT"}},
		"openssl":    {decision: DecisionUnevaluated, licenses: []string{}},
		"fontconfig": {decision: DecisionUnevaluated, licenses: []string{}},
		"libapr1t64": {decision: DecisionUnevaluated, licenses: []string{}},
	}
	everyLicense := map[string]concludedFinding{
		"catalina":   {decision: DecisionUnevaluated, licenses: []string{"Apache-2.0"}},
		"libexpat1":  {decision: DecisionUnevaluated, licenses: []string{"MIT"}},
		"openssl":    {decision: DecisionUnevaluated, licenses: []string{}},
		"fontconfig": {decision: DecisionUnevaluated, licenses: []string{"HPND-sell-variant"}},
		"libapr1t64": {decision: DecisionUnevaluated, licenses: []string{"Apache-2.0", "BSD-4-Clause-UC", "ISC", "Zlib"}},
	}

	tests := []struct {
		name               string
		policy             *Policy
		wantUniqueLicenses int
		wantUnlicensed     int
		wantFindings       map[string]concludedFinding
	}{
		{
			name:               "by default",
			policy:             &Policy{},
			wantUniqueLicenses: 6,
			wantUnlicensed:     1,
			wantFindings:       everyLicense,
		},
		{
			name:               "ignoring concluded",
			policy:             &Policy{IgnoreConcludedLicenses: true},
			wantUniqueLicenses: 2,
			wantUnlicensed:     3,
			wantFindings:       declaredOnly,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			orchestrator, err := NewOrchestrator(tt.policy)
			require.NoError(t, err)
			defer orchestrator.Close()

			response, err := orchestrator.List([]string{"grant", "list"}, tomcatSBOM(tomcatSPDX))
			require.NoError(t, err)

			evaluation, findings := findingsByPackage(t, response)
			assert.Equal(t, tt.wantUniqueLicenses, evaluation.Summary.Licenses.Unique)
			assert.Equal(t, tt.wantUnlicensed, evaluation.Summary.Packages.Unlicensed)
			assertConcludedFindings(t, tt.wantFindings, findings)
		})
	}
}

func TestLoadPolicy_IgnoreConcludedLicenses(t *testing.T) {
	policy, err := LoadPolicy([]byte("allow:\n  - MIT\n"))
	require.NoError(t, err)
	assert.False(t, policy.IgnoreConcludedLicenses, "the option is off unless the policy sets it")

	policy, err = LoadPolicy([]byte("allow:\n  - MIT\nignore-concluded-licenses: true\n"))
	require.NoError(t, err)
	assert.True(t, policy.IgnoreConcludedLicenses)
}

func TestRunResponse_PolicyJSON_IgnoreConcludedLicenses(t *testing.T) {
	policyJSON := func(policy *Policy) string {
		encoded, err := json.Marshal(NewRunResponse(nil, policy).Run.Policy)
		require.NoError(t, err)
		return string(encoded)
	}

	// the report of a run without the option has exactly the fields it had before the option existed
	assert.JSONEq(t,
		`{"rules":{"allow":["MIT"],"ignorePackages":null},"requireLicense":true,"requireKnownLicense":false}`,
		policyJSON(&Policy{Allow: []string{"MIT"}, RequireLicense: true}))

	assert.JSONEq(t,
		`{"rules":{"allow":["MIT"],"ignorePackages":null},"requireLicense":true,"requireKnownLicense":false,"ignoreConcludedLicenses":true}`,
		policyJSON(&Policy{Allow: []string{"MIT"}, RequireLicense: true, IgnoreConcludedLicenses: true}))
}

func TestWithoutConcludedLicenses(t *testing.T) {
	declared := func(value string) pkg.License {
		return pkg.License{Value: value, SPDXExpression: value, Type: license.Declared}
	}
	concluded := func(value string) pkg.License {
		return pkg.License{Value: value, SPDXExpression: value, Type: license.Concluded}
	}

	tests := []struct {
		name        string
		licenses    []pkg.License
		want        []pkg.License
		wantDropped int
	}{
		{
			name: "no licenses",
			want: []pkg.License{},
		},
		{
			name:     "declared only",
			licenses: []pkg.License{declared("MIT")},
			want:     []pkg.License{declared("MIT")},
		},
		{
			name:        "concluded only",
			licenses:    []pkg.License{concluded("MIT"), concluded("ISC")},
			want:        []pkg.License{},
			wantDropped: 2,
		},
		{
			// the same license declared and concluded is two entries, and the declared one stays
			name:        "same license declared and concluded",
			licenses:    []pkg.License{declared("MIT"), concluded("MIT")},
			want:        []pkg.License{declared("MIT")},
			wantDropped: 1,
		},
		{
			// only an explicit concluded type is dropped
			name:     "no type",
			licenses: []pkg.License{{Value: "MIT", SPDXExpression: "MIT"}},
			want:     []pkg.License{{Value: "MIT", SPDXExpression: "MIT"}},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, dropped := withoutConcludedLicenses(pkg.NewLicenseSet(tt.licenses...))
			assert.Equal(t, tt.wantDropped, dropped)
			assert.ElementsMatch(t, pkg.NewLicenseSet(tt.want...).ToSlice(), got.ToSlice())
		})
	}
}

func TestIgnoredConcluded(t *testing.T) {
	var ignored ignoredConcluded
	ignored.add(0, true) // a package with no licenses to begin with is not counted
	ignored.add(2, true)
	ignored.add(1, false)

	assert.Equal(t, ignoredConcluded{licenses: 3, packages: 2, unlicensed: 1}, ignored)
	assert.Equal(t, "ignored 3 concluded licenses on 2 packages, 1 of which are left with no licenses", ignored.String())
}
